/**
 * Shared exercise renderer and single-question practice session.
 *
 * The lesson player has its own seventeen-section flow; this module powers the
 * smaller drill sessions used by Grammar Academy, Practice Exercises and mock
 * exams. Every question is authored content — nothing is generated by an AI.
 */
import { escapeHtml, icon } from './ui.js';

export function normalizeAnswer(value) {
  return String(value ?? '')
    .toLocaleLowerCase('de-DE')
    .normalize('NFC')
    .replace(/[’‘]/g, "'")
    .replace(/\s+/g, ' ')
    .replace(/[.!?]+$/g, '')
    .trim();
}

export function drillBody(question) {
  const promptId = `drill-prompt-${question.id}`;
  if (question.type === 'mcq') {
    return `
      <fieldset class="exercise" data-question="${escapeHtml(question.id)}" data-type="mcq" aria-labelledby="${promptId}">
        <legend class="exercise__prompt" id="${promptId}">
          <span class="exercise__prompt-text">${escapeHtml(question.prompt)}</span>
        </legend>
        <div class="exercise__options">
          ${question.options
            .map(
              (option, index) => `
              <label class="option">
                <input type="radio" name="q-${escapeHtml(question.id)}" value="${index}" />
                <span class="option__mark" aria-hidden="true"></span>
                <span class="option__text">${escapeHtml(option)}</span>
              </label>`,
            )
            .join('')}
        </div>
        <div class="exercise__feedback" data-feedback hidden></div>
      </fieldset>`;
  }

  if (question.type === 'gap') {
    return `
      <div class="exercise" data-question="${escapeHtml(question.id)}" data-type="gap" role="group" aria-labelledby="${promptId}">
        <p class="exercise__prompt" id="${promptId}"><span class="exercise__prompt-text">${escapeHtml(question.prompt)}</span></p>
        <label class="gap-field">
          <span class="sr-only">Your answer</span>
          <input class="gap-input" type="text" autocomplete="off" autocapitalize="off" spellcheck="false"
            data-answer-input placeholder="Type the missing word" />
        </label>
        <div class="exercise__feedback" data-feedback hidden></div>
      </div>`;
  }

  return `
    <div class="exercise" data-question="${escapeHtml(question.id)}" data-type="order" role="group" aria-labelledby="${promptId}">
      <p class="exercise__prompt" id="${promptId}"><span class="exercise__prompt-text">${escapeHtml(question.prompt)}</span></p>
      <div class="order-builder" data-order>
        <div class="order-builder__answer" data-order-answer aria-live="polite">
          <span class="order-builder__placeholder">Click the words below in the correct order.</span>
        </div>
        <div class="order-builder__tokens" data-order-tokens aria-label="Word tokens">
          ${question.tokens
            .map(
              (token, index) => `<button class="order-token" type="button" data-token="${index}">${escapeHtml(
                token,
              )}</button>`,
            )
            .join('')}
        </div>
      </div>
      <div class="exercise__actions">
        <button class="btn btn--ghost btn--sm" type="button" data-order-clear>Clear</button>
      </div>
      <div class="exercise__feedback" data-feedback hidden></div>
    </div>`;
}

export function bindDrillInteractions(root) {
  root.querySelectorAll('[data-order]').forEach((builder) => {
    const answer = builder.querySelector('[data-order-answer]');
    const tokens = builder.querySelector('[data-order-tokens]');
    if (!answer || !tokens) return;

    const sync = () => {
      const hasToken = answer.querySelector('[data-token]');
      const placeholder = answer.querySelector('.order-builder__placeholder');
      if (hasToken && placeholder) placeholder.remove();
      if (!hasToken && !placeholder) {
        const span = document.createElement('span');
        span.className = 'order-builder__placeholder';
        span.textContent = 'Click the words below in the correct order.';
        answer.append(span);
      }
      answer.dispatchEvent(new CustomEvent('order-change', { bubbles: true }));
    };

    tokens.addEventListener('click', (event) => {
      const token = event.target.closest('[data-token]');
      if (!token || token.disabled) return;
      answer.append(token);
      sync();
    });

    answer.addEventListener('click', (event) => {
      const token = event.target.closest('[data-token]');
      if (!token || token.disabled) return;
      tokens.append(token);
      sync();
    });

    builder.querySelector('[data-order-clear]')?.addEventListener('click', () => {
      [...answer.querySelectorAll('[data-token]')].forEach((token) => tokens.append(token));
      sync();
    });
  });
}

export function selectedOrderAnswer(questionElement) {
  const answer = questionElement.querySelector('[data-order-answer]');
  return [...(answer?.querySelectorAll('[data-token]') || [])].map((button) => button.textContent).join(' ');
}

export function givenAnswer(question, element) {
  if (question.type === 'mcq') {
    const selected = element.querySelector('input[type="radio"]:checked');
    return selected ? question.options[Number(selected.value)] || '' : '';
  }
  if (question.type === 'gap') return element.querySelector('[data-answer-input]')?.value || '';
  return selectedOrderAnswer(element);
}

export function evaluateDrill(question, element) {
  if (question.type === 'mcq') {
    const selected = element.querySelector('input[type="radio"]:checked');
    return selected ? Number(selected.value) === question.answer : false;
  }
  if (question.type === 'gap') {
    const value = element.querySelector('[data-answer-input]')?.value || '';
    return question.answers.map(normalizeAnswer).includes(normalizeAnswer(value));
  }
  return normalizeAnswer(selectedOrderAnswer(element)) === normalizeAnswer(question.answer);
}

export function answerText(question) {
  if (question.type === 'mcq') return question.options[question.answer] || '';
  if (question.type === 'gap') return question.answers[0] || '';
  return question.answer;
}

export function drillFeedbackHtml(question, correct) {
  const answer = answerText(question);
  return `
    <span class="exercise__feedback-icon">${icon(correct ? 'check' : 'info')}</span>
    <div>
      <strong>${correct ? 'Correct' : 'Not quite'}</strong>
      ${correct ? '' : `<p>Correct answer: <span lang="de">${escapeHtml(answer)}</span></p>`}
      <p>${escapeHtml(question.explanation)}</p>
    </div>`;
}

function hasAnswer(question, element) {
  if (question.type === 'mcq') return Boolean(element.querySelector('input[type="radio"]:checked'));
  if (question.type === 'gap') return Boolean((element.querySelector('[data-answer-input]')?.value || '').trim());
  return Boolean(element.querySelector('[data-order-answer] [data-token]'));
}

/**
 * Run a sequence of authored questions inside `container`.
 *
 * @param {object} options
 * @param {HTMLElement} options.container
 * @param {Array} options.questions
 * @param {string} [options.intro]
 * @param {(session: {results: Array, correct: number, total: number, percent: number, minutes: number}) => void} [options.onFinish]
 * @param {string} [options.retryLabel]
 */
export function createDrillSession({
  container,
  questions,
  intro = '',
  onFinish,
  retryLabel = 'Practise again',
  showRetry = true,
}) {
  if (!container || !Array.isArray(questions) || questions.length === 0) return null;

  let queue = [...questions];
  let index = 0;
  let results = [];
  let answered = false;
  let finished = false;
  let startedAt = Date.now();

  container.innerHTML = `
    <div class="drill-session" data-drill-session>
      ${intro ? `<p class="drill-session__intro">${escapeHtml(intro)}</p>` : ''}
      <div class="drill-session__bar">
        <span class="drill-session__count" data-drill-count aria-live="polite"></span>
        <div class="progress drill-session__progress" role="progressbar" aria-label="Practice progress"
          aria-valuemin="0" aria-valuemax="${queue.length}" aria-valuenow="0" data-drill-progress>
          <span class="progress__bar" style="width: 0%"></span>
        </div>
      </div>
      <div class="drill-session__stage" data-drill-stage></div>
      <div class="drill-session__actions">
        <button class="btn btn--primary btn--sm" type="button" data-drill-check disabled>${icon('check')} Check answer</button>
        <button class="btn btn--soft btn--sm" type="button" data-drill-next hidden>Next question ${icon('arrow-right')}</button>
      </div>
      <div class="drill-session__result" data-drill-result hidden></div>
    </div>`;

  const stage = container.querySelector('[data-drill-stage]');
  const count = container.querySelector('[data-drill-count]');
  const progress = container.querySelector('[data-drill-progress]');
  const bar = progress?.querySelector('.progress__bar');
  const checkButton = container.querySelector('[data-drill-check]');
  const nextButton = container.querySelector('[data-drill-next]');
  const resultBox = container.querySelector('[data-drill-result]');
  const actions = container.querySelector('.drill-session__actions');

  function updateChrome() {
    const total = queue.length;
    count.textContent = `Question ${Math.min(index + 1, total)} of ${total}`;
    progress?.setAttribute('aria-valuemax', String(total));
    progress?.setAttribute('aria-valuenow', String(Math.min(index, total)));
    if (bar) bar.style.width = `${Math.round((Math.min(index, total) / total) * 100)}%`;
  }

  function renderQuestion() {
    answered = false;
    finished = false;
    const question = queue[index];
    stage.innerHTML = drillBody(question);
    bindDrillInteractions(stage);
    const element = stage.querySelector('[data-question]');
    checkButton.hidden = false;
    checkButton.disabled = true;
    nextButton.hidden = true;
    resultBox.hidden = true;
    actions.hidden = false;

    const refreshReady = () => {
      if (!answered) checkButton.disabled = !hasAnswer(question, element);
    };

    element.addEventListener('change', refreshReady);
    element.addEventListener('input', refreshReady);
    element.addEventListener('order-change', refreshReady);
    element.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' && question.type === 'gap' && !answered) {
        event.preventDefault();
        if (!checkButton.disabled) check();
      }
    });

    updateChrome();
    focusFirstControl(element);
  }

  function focusFirstControl(element) {
    const target =
      element.querySelector('input[type="radio"]') ||
      element.querySelector('[data-answer-input]') ||
      element.querySelector('[data-order-tokens] [data-token]');
    // Only steal focus when the session is already inside the viewport.
    if (target && container.getBoundingClientRect().top < window.innerHeight) {
      target.focus({ preventScroll: true });
    }
  }

  function check() {
    if (answered) return;
    const question = queue[index];
    const element = stage.querySelector('[data-question]');
    const correct = evaluateDrill(question, element);
    const given = givenAnswer(question, element);

    answered = true;
    results.push({
      question,
      drillId: question.id,
      correct,
      type: question.type,
      prompt: question.prompt,
      given,
      answer: answerText(question),
      explanation: question.explanation,
    });

    element.classList.add(correct ? 'is-correct' : 'is-wrong');
    const feedback = element.querySelector('[data-feedback]');
    if (feedback) {
      feedback.hidden = false;
      feedback.className = `exercise__feedback exercise__feedback--${correct ? 'correct' : 'incorrect'}`;
      feedback.innerHTML = drillFeedbackHtml(question, correct);
    }
    element.querySelectorAll('input, [data-token], [data-answer-input], [data-order-clear]').forEach((control) => {
      control.disabled = true;
    });
    checkButton.hidden = true;
    nextButton.hidden = false;
    nextButton.innerHTML =
      index === queue.length - 1
        ? `See results ${icon('award')}`
        : `Next question ${icon('arrow-right')}`;
    nextButton.focus({ preventScroll: true });
    updateChrome();
  }

  function finish() {
    finished = true;
    const total = results.length;
    const correct = results.filter((result) => result.correct).length;
    const percent = total ? Math.round((correct / total) * 100) : 0;
    const minutes = Math.max(1, Math.round((Date.now() - startedAt) / 60000));
    const missed = results.filter((result) => !result.correct);

    progress?.setAttribute('aria-valuenow', String(total));
    if (bar) bar.style.width = '100%';
    count.textContent = 'Session complete';
    stage.innerHTML = '';
    actions.hidden = true;
    resultBox.hidden = false;
    resultBox.innerHTML = `
      <div class="drill-result ${percent >= 70 ? 'drill-result--strong' : 'drill-result--building'}" role="status">
        <span class="drill-result__icon">${icon(percent >= 70 ? 'award' : 'rotate')}</span>
        <div class="drill-result__body">
          <p class="eyebrow">${percent >= 70 ? 'Strong session' : 'Keep building'}</p>
          <h3>${correct} of ${total} correct · ${percent}%</h3>
          <p>${escapeHtml(
            missed.length
              ? `${missed.length} question${missed.length === 1 ? '' : 's'} saved for mistake review. The explanation for each answer is shown as you practise.`
              : 'Every answer was correct. The next review will space these questions further apart.',
          )}</p>
          <div class="drill-result__actions">
            ${
              showRetry && missed.length
                ? `<button class="btn btn--soft btn--sm" type="button" data-drill-retry>${icon('rotate')} ${escapeHtml(
                    retryLabel,
                  )} (${missed.length})</button>`
                : ''
            }
            ${
              showRetry && !missed.length
                ? `<button class="btn btn--soft btn--sm" type="button" data-drill-retry>${icon('rotate')} ${escapeHtml(
                    retryLabel,
                  )}</button>`
                : ''
            }
          </div>
        </div>
      </div>`;

    const payload = { results, correct, total, percent, minutes };
    onFinish?.(payload);

    resultBox.querySelector('[data-drill-retry]')?.addEventListener('click', () => {
      queue = missed.length ? missed.map((result) => result.question) : [...questions];
      index = 0;
      results = [];
      startedAt = Date.now();
      renderQuestion();
    });
  }

  nextButton.addEventListener('click', () => {
    if (!answered) return;
    if (index >= queue.length - 1) {
      finish();
      return;
    }
    index += 1;
    renderQuestion();
  });

  checkButton.addEventListener('click', () => {
    if (!checkButton.disabled) check();
  });

  renderQuestion();
  return {
    get finished() {
      return finished;
    },
    results: () => [...results],
  };
}
